<template>
  <section class="card min-w-0 text-gray-800 dark:text-gray-100 space-y-5 p-4 md:p-6" data-bank-importer>
    <header class="flex flex-wrap justify-between gap-2"><h2 class="font-semibold">銀行明細の取込</h2><button class="text-sm text-gray-500" @click="emit('close')">閉じる</button></header>
    <p class="text-sm leading-relaxed text-gray-500">Excel・CSVの列を割り当てて取り込みます。原本を保管し、別ファイルの同じ内容は自動で統合しません。銀行サイトへの接続・振込は行いません。</p>
    <p v-if="error" role="alert" class="break-words text-sm text-red-600 dark:text-red-300">{{ error }}</p>
    <div class="grid min-w-0 gap-3 md:grid-cols-2"><label class="block text-sm">銀行口座<select v-model="accountId" class="input max-w-full rounded-xl border border-gray-200 bg-white px-3 py-2 dark:border-slate-700 dark:bg-slate-800 dark:text-white mt-1 w-full" data-bank-account><option value="">口座を選択してください</option><option v-for="a in accounts" :key="a.id" :value="a.id">{{ a.name }}（{{ a.currency }}）</option></select></label><form class="flex min-w-0 flex-wrap gap-2" @submit.prevent="createAccount"><label class="min-w-0 flex-1 text-sm">新しい口座名<input type="text" v-model="accountName" class="input max-w-full rounded-xl border border-gray-200 bg-white px-3 py-2 dark:border-slate-700 dark:bg-slate-800 dark:text-white mt-1 w-full" maxlength="100" required></label><label class="w-24 text-sm">通貨<input type="text" v-model="accountCurrency" class="input max-w-full rounded-xl border border-gray-200 bg-white px-3 py-2 dark:border-slate-700 dark:bg-slate-800 dark:text-white mt-1 w-full" maxlength="3" required></label><button class="btn btn-secondary self-end" :disabled="busy">口座を追加</button></form></div>
    <label class="block text-sm">Excel・CSV（最大10MB）<input class="mt-2 block w-full min-w-0 text-sm" data-bank-file type="file" accept=".csv,.tsv,.txt,.xlsx,.xls" :disabled="busy" @change="upload"></label>
    <label class="block text-sm">保存済みファイルから選ぶ（自動取得・要確認の明細もここから割り当てます）<select data-bank-file-picker class="input mt-1 w-full max-w-full rounded-xl border border-gray-200 bg-white px-3 py-2 dark:border-slate-700 dark:bg-slate-800 dark:text-white" :value="doc?.id || ''" :disabled="busy" @change="pickFile($event)"><option value="">選択してください</option><option v-for="f in files" :key="f.id" :value="f.id">{{ f.name }} · {{ fileState(f) }} · {{ (f.createdAt || '').slice(0, 10) }}</option></select></label>
    <template v-if="doc">
      <p class="break-words text-xs text-gray-500">{{ doc.name }} · {{ Math.ceil(doc.size/1024) }} KB · 原本を保存済み</p>
      <div class="flex flex-wrap items-end gap-3"><label class="text-sm">シート<select v-model="sheet" class="input max-w-full rounded-xl border border-gray-200 bg-white px-3 py-2 dark:border-slate-700 dark:bg-slate-800 dark:text-white mt-1 w-full" @change="readSheet"><option v-for="s in doc.sheetNames" :key="s">{{ s }}</option></select></label><label class="text-sm">見出し行<input v-model="headerRow" class="input max-w-full rounded-xl border border-gray-200 bg-white px-3 py-2 dark:border-slate-700 dark:bg-slate-800 dark:text-white mt-1 w-24" type="number" min="1" @change="readSheet"></label><label class="min-w-0 flex-1 text-sm">テンプレート<select v-model="templateId" data-bank-template class="input max-w-full rounded-xl border border-gray-200 bg-white px-3 py-2 dark:border-slate-700 dark:bg-slate-800 dark:text-white mt-1 w-full" @change="applyTemplate"><option value="">列名から推定</option><option v-for="t in templates" :key="t.id" :value="t.id">{{ t.name }}</option></select></label></div>
      <div v-if="sheetData" class="space-y-4">
        <div class="grid gap-3 md:grid-cols-2"><label v-for="[key,label] in BANK_FIELDS" :key="key" class="min-w-0 text-sm">{{ label }}<select v-model="mapping[key]" class="input max-w-full rounded-xl border border-gray-200 bg-white px-3 py-2 dark:border-slate-700 dark:bg-slate-800 dark:text-white mt-1 w-full" :data-bank-field="key"><option value="">割り当てない</option><option v-for="(h,i) in sheetData.headers" :key="i" :value="String(i)">{{ i+1 }}列：{{ h || '見出しなし' }}</option></select></label></div>
        <fieldset class="min-w-0 space-y-2" data-bank-date-parts><legend class="text-sm">取引日が年・月・日の3列に分かれている場合</legend><p class="text-xs text-gray-500">「取引日」を割り当てず、年・月・日の3列をすべて割り当ててください。「取引日」を割り当てた場合はそちらを使います。元ファイルは変更しません。</p><div class="grid gap-3 md:grid-cols-3"><label v-for="[key,label] in BANK_DATE_PARTS" :key="key" class="min-w-0 text-sm">{{ label }}<select v-model="mapping[key]" class="input max-w-full rounded-xl border border-gray-200 bg-white px-3 py-2 dark:border-slate-700 dark:bg-slate-800 dark:text-white mt-1 w-full" :data-bank-field="key"><option value="">割り当てない</option><option v-for="(h,i) in sheetData.headers" :key="i" :value="String(i)">{{ i+1 }}列：{{ h || '見出しなし' }}</option></select></label></div></fieldset>
        <label v-if="mapping.amount!==''" class="block text-sm">金額列の符号<select v-model="amountSign" data-bank-amount-sign class="input mt-1 w-full max-w-full rounded-xl border border-gray-200 bg-white px-3 py-2 dark:border-slate-700 dark:bg-slate-800 dark:text-white"><option v-for="[key,label] in BANK_AMOUNT_SIGNS" :key="key" :value="key">{{ label }}</option></select><span class="mt-1 block text-xs text-gray-500">元ファイルの表記に合わせて選択してください。出金／入金の別列がある行はそちらを優先し、金額列を使う行は明示された入出金区分を優先します。</span></label>
        <label v-if="mapping.transactionId!==''" class="flex items-start gap-2 text-sm"><input v-model="transactionIdConfirmed" class="mt-1" type="checkbox">この列は銀行が発行した一意の取引IDです（摘要・メモではありません）。</label>
        <details><summary class="cursor-pointer text-sm text-gray-500">元データの先頭20行（全{{ sheetData.rowCount }}行）</summary><div class="mt-2 max-w-full overflow-auto"><table class="text-xs"><thead><tr><th v-for="(h,i) in sheetData.headers" :key="i" class="whitespace-nowrap p-2 text-left">{{ h }}</th></tr></thead><tbody><tr v-for="(r,i) in sheetData.rows" :key="i"><td v-for="(v,j) in r" :key="j" class="whitespace-nowrap p-2">{{ v }}</td></tr></tbody></table></div></details>
        <label class="block text-sm">この割り当てのテンプレート名（任意）<input type="text" v-model="templateName" data-bank-template-name class="input max-w-full rounded-xl border border-gray-200 bg-white px-3 py-2 dark:border-slate-700 dark:bg-slate-800 dark:text-white mt-1 w-full" maxlength="100"></label><button class="btn btn-secondary" :disabled="busy || !accountId" data-bank-preview @click="preview">内容をプレビュー</button>
      </div>
      <section v-if="previewData" class="space-y-3 rounded-xl bg-gray-50 p-4 dark:bg-gray-800" data-bank-preview-result><h3 class="text-sm font-medium">新規 {{ previewData.counts.new }}件 · 取込済み {{ previewData.counts.existing }}件</h3><p v-if="previewData.pairs.length" class="text-sm text-amber-700 dark:text-amber-300">重複・訂正の可能性が{{ previewData.pairs.length }}件あります。両方の明細を保持し、取込後に確認できます。</p><p v-for="r in previewData.rows.slice(0,50)" :key="r.key" data-bank-preview-row :data-bank-direction="r.direction" class="break-words text-xs">{{ r.date }} · {{ r.description }} · {{ r.direction==='out'?'出金':'入金' }} {{ Math.abs(r.amount).toLocaleString('ja-JP') }} {{ r.currency }}<span v-if="r.identicalCount>1"> · 同一内容{{ r.identicalCount }}件（別々の行を保持）</span></p><button class="btn btn-primary" :disabled="busy" data-bank-import-confirm @click="runImport">確認して取り込む</button></section>
      <p v-if="result" class="text-sm text-green-700 dark:text-green-300" role="status">{{ result.rows.length }}件を確認しました。下の明細から支払いを照合できます。</p>
    </template>
  </section>
</template>
<script setup lang="ts">
import { BANK_FIELDS, BANK_DATE_PARTS, BANK_AMOUNT_SIGNS, type BankAmountSign } from '~/shared/finance-payment-match.mjs'
import { useUserStore } from '~/stores/user'
const props=defineProps<{fileId?:string}>(),emit=defineEmits<{(e:'imported'):void;(e:'close'):void}>(),user=useUserStore(),api='/api/finance-payments/bank/'
const accounts=ref<any[]>([]),templates=ref<any[]>([]),files=ref<any[]>([]),accountId=ref(''),accountName=ref(''),accountCurrency=ref('JPY'),busy=ref(false),error=ref(''),doc=ref<any>(null),sheet=ref(''),headerRow=ref<any>(''),sheetData=ref<any>(null),previewData=ref<any>(null),result=ref<any>(null),templateId=ref(''),amountSign=ref<BankAmountSign>('outflow-positive'),templateName=ref(''),transactionIdConfirmed=ref(false),mapping=reactive<Record<string,string>>(Object.fromEntries([...BANK_FIELDS,...BANK_DATE_PARTS].map(([k])=>[k,''])))
async function run(fn:()=>Promise<void>){busy.value=true;error.value='';try{await fn()}catch(e:any){error.value=e.data?.data?.message||e.message}finally{busy.value=false}}
async function lists(){const [a,t,f]:any[]=await Promise.all([$fetch(api+'accounts',{headers:user.authHeader}),$fetch(api+'templates',{headers:user.authHeader}),$fetch(api+'files',{headers:user.authHeader})]);accounts.value=a.accounts;templates.value=t.templates;files.value=f.files}
const fileState=(f:any)=>f.capture?((f.capture.state==='needs_review'?'自動取得・要確認':f.capture.state==='imported'?'自動取得・取込済み':'自動取得')+' · 口座照合 '+['未確認','確認済み'][Number(f.capture.labelChecked===true)]):'アップロード'
// The retained-file picker: the next lane of a needs_review capture (and of any earlier upload) — the file is selected, its
// first sheet read, and the capture's bank account preselected; preview and import then run on the owner path.
async function pickFile(event:Event|string){const id=typeof event==='string'?event:(event.target as HTMLSelectElement).value;if(!id)return;await run(async()=>{if(!files.value.length)await lists();const f=files.value.find(x=>x.id===id);if(!f)return;doc.value={...f};sheet.value=f.sheetNames?.[0]||'';headerRow.value='';previewData.value=null;result.value=null;if(f.capture?.bankAccountId&&accounts.value.some(a=>a.id===f.capture.bankAccountId))accountId.value=f.capture.bankAccountId;await readSheetNow()})}
watch(()=>props.fileId,v=>{if(v)pickFile(v)})
async function createAccount(){await run(async()=>{const r:any=await $fetch(api+'accounts',{method:'POST',headers:user.authHeader,body:{name:accountName.value,currency:accountCurrency.value}});await lists();accountId.value=r.account.id;accountName.value=''})}
async function upload(event:Event){const input=event.target as HTMLInputElement,file=input.files?.[0];if(!file)return;await run(async()=>{const ext=file.name.toLowerCase().split('.').pop(),type=file.type||(ext==='xlsx'?'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet':ext==='xls'?'application/vnd.ms-excel':'text/csv'),r:any=await $fetch(api+'files',{method:'POST',query:{name:file.name},headers:{...user.authHeader,'Content-Type':type},body:file});doc.value=r.document;sheet.value=doc.value.sheetNames[0];headerRow.value='';previewData.value=null;result.value=null;await readSheetNow()});input.value=''}
async function readSheetNow(){sheetData.value=await $fetch(api+'files/'+doc.value.id+'/sheet',{headers:user.authHeader,query:{sheet:sheet.value,headerRow:headerRow.value}});headerRow.value=sheetData.value.headerRow;for(const [k] of [...BANK_FIELDS,...BANK_DATE_PARTS])mapping[k]=sheetData.value.mapping?.[k]??'';amountSign.value='outflow-positive';templateId.value='';templateName.value='';previewData.value=null;result.value=null;transactionIdConfirmed.value=false}
async function readSheet(){await run(readSheetNow)}
function applyTemplate(){const t=templates.value.find(t=>t.id===templateId.value),m=t?.mapping||sheetData.value?.mapping||{};for(const [k] of [...BANK_FIELDS,...BANK_DATE_PARTS])mapping[k]=m[k]!==undefined&&m[k]!==''&&Number(m[k])<sheetData.value.headers.length?String(m[k]):'';templateName.value=t?.name||'';amountSign.value=t?.amountSign||'outflow-positive';transactionIdConfirmed.value=false}
const body=()=>({sheet:sheet.value,headerRow:Number(headerRow.value),bankAccountId:accountId.value,mapping:{...mapping},amountSign:amountSign.value,transactionIdConfirmed:transactionIdConfirmed.value,templateName:templateName.value})
async function preview(){await run(async()=>{previewData.value=await $fetch(api+'files/'+doc.value.id+'/preview',{method:'POST',headers:user.authHeader,body:body()});result.value=null})}
async function runImport(){await run(async()=>{result.value=await $fetch(api+'files/'+doc.value.id+'/import',{method:'POST',headers:user.authHeader,body:{...body(),confirm:true}});previewData.value=null;await lists();emit('imported')})}
watch([accountId,mapping,amountSign,transactionIdConfirmed,templateName],()=>{previewData.value=null;result.value=null},{deep:true})
onMounted(()=>run(async()=>{await lists();if(props.fileId)await pickFile(props.fileId)}))
</script>
